using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchDataTool
{
    [McpServerTool(Name = "fetch_data"), Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The API path to query (e.g. \"/users/1\").")] string path,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt(Name = "summarize"), Description("Summarize the provided text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum length in sentences.")] int? maxSentences = 3)
    {
        var systemMsg = maxSentences.HasValue
            ? $"You are a summarization assistant. Summarize the user's text in at most {maxSentences} sentences."
            : "You are a summarization assistant. Provide a concise summary of the user's text.";

        return new GetPromptResult
        {
            Description = "Summarize the provided text",
            Messages =
            [
                new PromptMessage { Role = Role.Assistant, Content = new Content { Type = "text", Text = systemMsg } },
                new PromptMessage { Role = Role.User, Content = new Content { Type = "text", Text = text } },
            ]
        };
    }
}

